package com.medtrack.warehouse.controller; import com.medtrack.warehouse.dto.*; import com.medtrack.warehouse.service.WarehouseService; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/warehouses") public class WarehouseController {private final WarehouseService service;public WarehouseController(WarehouseService s){service=s;}@GetMapping @PreAuthorize("hasAuthority('WAREHOUSE_READ')") public Page<WarehouseResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(PageRequest.of(page,Math.min(Math.max(1,size),100)));}@PostMapping @PreAuthorize("hasAuthority('WAREHOUSE_CREATE')") public ResponseEntity<WarehouseResponse> create(@Valid @RequestBody WarehouseRequest r){return ResponseEntity.status(201).body(service.create(r));}@GetMapping("/{id}")@PreAuthorize("hasAuthority('WAREHOUSE_READ')")public WarehouseResponse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}")@PreAuthorize("hasAuthority('WAREHOUSE_UPDATE')")public WarehouseResponse update(@PathVariable UUID id,@Valid @RequestBody WarehouseRequest r){return service.update(id,r);}@GetMapping("/{id}/storage-locations")@PreAuthorize("hasAuthority('WAREHOUSE_READ')")public List<StorageLocationResponse> locations(@PathVariable UUID id){return service.locations(id);}@PostMapping("/{id}/storage-locations")@PreAuthorize("hasAuthority('WAREHOUSE_UPDATE')")public ResponseEntity<StorageLocationResponse> add(@PathVariable UUID id,@Valid @RequestBody StorageLocationRequest r){return ResponseEntity.status(201).body(service.addLocation(id,r));}}
